<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{useRouter}from'vue-router';import{api,type ApiResponse}from'@whaashop/shared';
interface Item{id:number;skuId:number;productName:string;image?:string;spec:string;price:number;quantity:number;checked:boolean;stock:number}
interface Address{id:number;receiverName:string;phone:string;province?:string;city?:string;district?:string;detail:string;isDefault:boolean}
const rows=ref<Item[]>([]),addresses=ref<Address[]>([]),router=useRouter(),error=ref(''),loading=ref(true),addressLoading=ref(false),submitting=ref(false),addressDialog=ref(false),selectedAddressId=ref<number>(),removingId=ref<number>();
const checkedRows=computed(()=>rows.value.filter(v=>v.checked)),total=computed(()=>checkedRows.value.reduce((sum,v)=>sum+Number(v.price)*v.quantity,0)),allChecked=computed({get:()=>!!rows.value.length&&rows.value.every(v=>v.checked),set:value=>toggleAll(value)});
async function load(){loading.value=true;try{rows.value=(await api.get<ApiResponse<Item[]>>('/shop/cart')).data.data.map(item=>({...item,spec:formatSpec(item.spec)}))}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function update(item:Item){item.quantity=Math.max(1,Math.min(item.stock,item.quantity));await api.put(`/shop/cart/${item.id}`,{quantity:item.quantity,checked:item.checked})}
async function changeQuantity(item:Item,step:number){const next=Math.max(1,Math.min(item.stock,item.quantity+step));if(next===item.quantity)return;item.quantity=next;await update(item)}
async function toggleAll(value:boolean){rows.value.forEach(item=>item.checked=value);await Promise.all(rows.value.map(update))}
async function remove(id:number){await api.delete(`/shop/cart/${id}`);rows.value=rows.value.filter(item=>item.id!==id);removingId.value=undefined}
async function openCheckout(){error.value='';if(!checkedRows.value.length){error.value='请先选择要结算的商品';return}addressDialog.value=true;addressLoading.value=true;try{addresses.value=(await api.get<ApiResponse<Address[]>>('/shop/addresses')).data.data;selectedAddressId.value=addresses.value.find(a=>a.isDefault)?.id??addresses.value[0]?.id}catch(e){error.value=(e as Error).message}finally{addressLoading.value=false}}
async function checkout(){const address=addresses.value.find(a=>a.id===selectedAddressId.value);if(!address)return;submitting.value=true;error.value='';try{await api.post('/shop/orders',{cartIds:checkedRows.value.map(v=>v.id),receiverName:address.receiverName,receiverPhone:address.phone,receiverAddress:fullAddress(address)});addressDialog.value=false;router.push('/orders')}catch(e){error.value=(e as Error).message}finally{submitting.value=false}}
function fullAddress(address:Address){return[address.province,address.city,address.district,address.detail].filter(Boolean).join(' ')}
function money(value:number){return Number(value).toFixed(2)}
function formatSpec(value?:string){if(!value?.trim())return'默认规格';try{const parsed=JSON.parse(value);if(Array.isArray(parsed))return parsed.map(formatValue).filter(Boolean).join(' · ')||'默认规格';if(parsed&&typeof parsed==='object')return Object.entries(parsed).filter(([,v])=>v!==null&&v!==undefined&&String(v).trim()).map(([k,v])=>`${specLabel(k)}：${formatValue(v)}`).join(' · ')||'默认规格';return String(parsed)||'默认规格'}catch{return value.replace(/[{}"']/g,'').replace(/:/g,'：').replace(/,/g,' · ')||'默认规格'}}
function formatValue(value:unknown):string{if(value&&typeof value==='object')return Object.entries(value).map(([k,v])=>`${specLabel(k)}：${formatValue(v)}`).join(' · ');return String(value)}
function specLabel(key:string){return({color:'颜色',size:'规格',switch:'轴体',storage:'容量',version:'版本'}as Record<string,string>)[key]??key}
onMounted(load)
</script>

<template><div class="cart-page"><div class="container"><section class="cart-heading"><div><span>SHOPPING CART</span><h1>购物车</h1><p>确认商品与数量，选择心仪好物一起结算</p></div><div><b>{{rows.length}}</b><small>件商品</small></div></section><div v-if="loading" class="cart-loading"><i v-for="n in 3" :key="n"></i></div><div v-else-if="!rows.length" class="cart-empty"><span>▱</span><h2>购物车还是空的</h2><p>去挑选一些喜欢的商品吧</p><router-link class="btn" to="/">去逛商城</router-link></div><template v-else><section class="cart-panel"><div class="cart-toolbar"><label><input v-model="allChecked" type="checkbox"><i></i>全选</label><span>已选择 {{checkedRows.length}} 件商品</span></div><article v-for="item in rows" :key="item.id" :class="['cart-item',{checked:item.checked}]"><label class="cart-check"><input v-model="item.checked" type="checkbox" @change="update(item)"><i></i></label><div class="cart-image"><img v-if="item.image" :src="item.image" :alt="item.productName"><span v-else>商品</span></div><div class="cart-product"><b>{{item.productName}}</b><span>{{item.spec}}</span><small>库存 {{item.stock}} 件</small></div><div class="cart-price"><small>单价</small><b>¥{{money(item.price)}}</b></div><div class="cart-quantity"><small>数量</small><div><button :disabled="item.quantity<=1" @click="changeQuantity(item,-1)">−</button><input v-model.number="item.quantity" type="number" min="1" :max="item.stock" @change="update(item)"><button :disabled="item.quantity>=item.stock" @click="changeQuantity(item,1)">＋</button></div></div><div class="cart-subtotal"><small>小计</small><b>¥{{money(Number(item.price)*item.quantity)}}</b></div><div class="cart-remove"><button v-if="removingId!==item.id" title="删除商品" aria-label="删除商品" @click="removingId=item.id"><span>⌫</span></button><div v-else class="remove-confirm"><span>确认删除？</span><button @click="remove(item.id)">删除</button><button @click="removingId=undefined">取消</button></div></div></article></section><p v-if="error" class="cart-error">{{error}}</p><section class="cart-summary"><div><span>已选 {{checkedRows.length}} 件</span><small>订单运费及优惠以提交时为准</small></div><div class="cart-total"><span>合计</span><b><i>¥</i>{{money(total)}}</b></div><button :disabled="!checkedRows.length" @click="openCheckout">提交订单</button></section></template></div></div>

<Teleport to="body"><transition name="cart-modal"><div v-if="addressDialog" class="address-mask" @click.self="addressDialog=false"><section class="checkout-address" role="dialog" aria-modal="true" aria-label="选择收货地址"><header><div><span>DELIVERY ADDRESS</span><h2>选择收货地址</h2><p>订单将配送至你选择的地址</p></div><button aria-label="关闭" @click="addressDialog=false">×</button></header><div class="address-content"><div v-if="addressLoading" class="address-loading">正在加载收货地址…</div><div v-else-if="!addresses.length" class="no-address"><span>⌖</span><h3>还没有收货地址</h3><p>需要先添加收货地址才能提交订单</p><router-link class="btn" to="/addresses?new=1&return=/cart">＋ 新增收货地址</router-link></div><template v-else><label v-for="address in addresses" :key="address.id" :class="['address-option',{selected:selectedAddressId===address.id}]"><input v-model="selectedAddressId" type="radio" :value="address.id"><i></i><div><div><b>{{address.receiverName}}</b><span>{{address.phone}}</span><em v-if="address.isDefault">默认地址</em></div><p>{{fullAddress(address)}}</p></div><strong>✓</strong></label><router-link class="add-address-link" to="/addresses?return=/cart">＋ 管理或新增收货地址</router-link></template></div><footer v-if="addresses.length"><div><span>应付合计</span><b>¥{{money(total)}}</b></div><button :disabled="!selectedAddressId||submitting" @click="checkout">{{submitting?'正在提交…':'确认地址并提交'}}</button></footer></section></div></transition></Teleport></template>

